import fitz, numpy as np
d = fitz.open('eprint/gann_final.pdf')
p = d[0]
RED = (0.9922000169754028, 0.40779998898506165, 0.4235000014305115)
def pts_of(dr):
    pts=[]
    for it in dr['items']:
        if it[0]=='l':
            pts.append((it[1].x,it[1].y)); pts.append((it[2].x,it[2].y))
        elif it[0]=='c':
            for pt in it[1:]:
                pts.append((pt.x,pt.y))
        elif it[0]=='re':
            r=it[1]; pts.append((r.x0,r.y0)); pts.append((r.x1,r.y1))
    return np.array(pts)
for i,dr in enumerate(p.get_drawings()):
    if dr.get('color')==RED or dr.get('fill')==RED:
        pts = pts_of(dr)
        print(i, 'stroke' if dr.get('color')==RED else 'fill', 'w=',dr.get('width'),
              'n=',len(dr['items']), 'xrange',pts[:,0].min().round(1),pts[:,0].max().round(1),
              'yrange',pts[:,1].min().round(1),pts[:,1].max().round(1))
